/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for populating the TMS engine temp table (calculation table)
/// </summary>
abstract class METTMSEngineLinesTmpBuilder
{
    METTMSEngineSalesOrderProccessLinesTmp processLinesTmp;
    SalesTable          salesTable;
    InventLocation      inventLocation;
    METInventLocation   metInventLocation;
    InventParameters    inventParameters;
    METTobaccoRepackQty tobaccoRepackQtyFactor;
    METTobaccoRepackQty standardRepackQtyFactor;
    TMSCarrierCode      carrierCode;
    boolean             isSalesOrderPerishable;
    boolean             isToteCustomer;
    InventLocationId    prevInventLocationId;
    boolean             hasCCR;

}

Method.Source:
/// <summary>
/// Manages the lineShipQty variable
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <returns>Sales order quantity</returns>
abstract protected SalesOrderedQty lineShipQty(SalesLine _salesLine)
{

}

/// <summary>
/// Get the warehouse id, custom secondaryInventLocationId if populated or std InventLocationId
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <returns>Warehouse id</returns>
protected InventLocationId getInventLocationId(SalesLine _salesLine)
{
    METSalesLine metSalesLine = METSalesLine::find(_salesLine.RecId);
    return metSalesLine.SecondaryInventLocationId ? metSalesLine.SecondaryInventLocationId : _salesLine.inventDim().InventLocationId;
}

/// <summary>
/// As common rule CCR is no except for METTMSEngineLinesTmpBuilder_PackingSlip
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <returns>Yes if supplier warehouse has CCR; otherwise, false.</returns>
protected NoYes setSuppWhsHasCCR(SalesLine _salesLine)
{
    // For CB624, CCR flag always set to No
    return NoYes::No;
}

/// <summary>
/// Constructs a new TMS engine lines temp builder.
/// </summary>
/// <param name = "_tmsEngineProcess">METTMSEngineSalesOrderProcess</param>
/// <param name = "_salesTable">Sales order header record</param>
/// <param name = "_shipmentId">SO finalisation shipment id</param>
/// <param name = "_wmsPicklistNumber">AIS WMS picking list number</param>
/// <returns>An instance of <c>METTMSEngineLinesTmpBuilder</c></returns>
public static METTMSEngineLinesTmpBuilder construct(METTMSEngineSalesOrderProcess _tmsEngineProcess, SalesTable _salesTable, METShipmentId _shipmentId = "", METWMSPicklistNumber _wmsPicklistNumber = "")
{
    METTMSEngineLinesTmpBuilder result;
    boolean error = false;

    switch (_tmsEngineProcess)
    {
        case (METTMSEngineSalesOrderProcess::Cancellation) :
        case (METTMSEngineSalesOrderProcess::Creation) :
            result = new METTMSEngineLinesTmpBuilder_Creation(_salesTable);                
            break;

        //CB625_TMSSOPickingListExtraction
        case (METTMSEngineSalesOrderProcess::PickingList) :
            result = new METTMSEngineLinesTmpBuilder_PickingList(_salesTable, _wmsPicklistNumber);
            break;

        // CB626_TMSEngineSOPackingSlip
        case (METTMSEngineSalesOrderProcess::PackingSlip) :
            result = new METTMSEngineLinesTmpBuilder_PackingSlip(_salesTable, _shipmentId, _wmsPicklistNumber);
            break;

        default:
            error = true;
            break;
    }

    if (error)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return result;
}

/// <summary>
/// Similar to what we had in METTMSEngineSalesOrderProccess\initTmpTable
/// </summary>
/// <returns>Temp table with all records inserted</returns>
public METTMSEngineSalesOrderProccessLinesTmp populateTmpTable()
{
    QueryRun qr = new QueryRun(this.initQuery());

    while (qr.next())
    {
        this.createTempTableRecords(qr);
    }

    return processLinesTmp;
}

/// <summary>
/// Get the hasCCR parameter
/// </summary>
/// <returns>true if at least one record CCR; otherwise, false.</returns>
public boolean hasCCR()
{
    return hasCCR;
}

/// <summary>
/// initialize default parameters
/// </summary>
/// <param name = "_salesTable">SalesTable record</param>
protected void init(SalesTable _salesTable)
{
    salesTable              = _salesTable;
    inventParameters        = InventParameters::find();
    carrierCode             = TMSSalesTable::find(_salesTable.SalesId).CarrierCode;
    isSalesOrderPerishable  = _salesTable.METIsSalesOrderPerishable();
    isToteCustomer          = CustTable::METIsToteCustomer(salesTable.CustAccount, salesTable.DataAreaId);
}

/// <summary>
/// initialize default parameters based on the line WH
/// </summary>
/// <param name = "_salesLine"><c>SalesLine</c> record</param>
protected void initSalesLineVariables(SalesLine _salesLine)
{
    InventLocationId inventLocationId = this.getInventLocationId(_salesLine);

    // to avoid resetting variables if the WH hasn't change
    if (inventLocationId != prevInventLocationId)
    {
        inventLocation          = InventLocation::find(inventLocationId);
        metInventLocation       = METInventLocation::findByInventLocationId(inventLocationId);

        // Added as never initialized
        /*whsPalletVolume = METInventLocation.WHSPalletVolume;
        whsPalletWeight = METInventLocation.WHSPalletWeight;

        this.initValuesFromContainerType(inventParameters, inventLocationId);*/

        this.initRepackQtyFactor(salesTable, inventParameters, isToteCustomer, inventLocationId);

        prevInventLocationId = inventLocationId;
    }
}

